// Typed access to the mapgen-server API. The types come from the Rust
// definitions (generated by ts-rs into ./types), so a server change that the
// front-end does not follow fails `npm run check`.
import type { ErrorDetail } from './types/ErrorDetail';
import type { ApiError } from './types/ApiError';
import type { BodySizes } from './types/BodySizes';
import type { DisplayedSize } from './types/DisplayedSize';
import type { FormSpec } from './types/FormSpec';
import type { GenerateStarted } from './types/GenerateStarted';
import type { SystemCreated } from './types/SystemCreated';
import type { SystemName } from './types/SystemName';
import type { SystemQuery } from './types/SystemQuery';
import type { SystemRequest } from './types/SystemRequest';
import type { SystemSummary } from './types/SystemSummary';
import type { HexMap } from './types/HexMap';
import type { HexRequest } from './types/HexRequest';
import type { JobInfo } from './types/JobInfo';
import type { JobStatus } from './types/JobStatus';
import type { PresetInfo } from './types/PresetInfo';
import type { RiversFile } from './types/RiversFile';
import type { WorldMetadata } from './types/WorldMetadata';

/** An API call that failed, with the server's message and, when it sent one, the reason as data. */
export class ApiFailure extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly detail?: ErrorDetail,
  ) {
    super(message);
    this.name = 'ApiFailure';
  }
}

function isApiError(body: unknown): body is ApiError {
  return typeof body === 'object' && body !== null && typeof (body as ApiError).error === 'string';
}

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, init);
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    throw new ApiFailure(
      response.status,
      isApiError(body) ? body.error : response.statusText,
      isApiError(body) ? (body.detail ?? undefined) : undefined,
    );
  }
  // The server produces these bodies from the same types: trusted shape.
  // Some answers (204, 202 of a cancellation) have no body.
  const text = await response.text();
  return (text === '' ? undefined : JSON.parse(text)) as T;
}

function fileInit(signal?: AbortSignal): RequestInit {
  return signal ? { cache: 'no-cache', signal } : { cache: 'no-cache' };
}

export const api = {
  presets: () => call<PresetInfo[]>('/api/presets'),
  form: () => call<FormSpec>('/api/form'),
  // World files keep their URL when a world is regenerated under the same
  // id: revalidate them ('no-cache', a 304 when unchanged).
  /** The metadata of a body at resolution `size` (`WxH`, see sizeName). */
  metadata: (id: string, size: string, signal?: AbortSignal) =>
    call<WorldMetadata>(worldFile(id, size, 'raw_data/world.json'), fileInit(signal)),
  /**
   * The metadata of a body seen from another body's view (the planet in a
   * moon's sky): a peek, which does not mark the body opened (see `peeked`).
   */
  peekMetadata: (id: string, size: string, signal?: AbortSignal) =>
    call<WorldMetadata>(peeked(worldFile(id, size, 'raw_data/world.json')), fileInit(signal)),
  rivers: (id: string, size: string, file: string, signal?: AbortSignal) =>
    call<RiversFile>(worldFile(id, size, `raw_data/${file}`), fileInit(signal)),
  /** The rivers of a body seen from another body's view: a peek, see `peekMetadata`. */
  peekRivers: (id: string, size: string, file: string, signal?: AbortSignal) =>
    call<RiversFile>(peeked(worldFile(id, size, `raw_data/${file}`)), fileInit(signal)),
  /** The resolutions of a generated body: on disk, displayed, being generated, offered. */
  sizes: (id: string, signal?: AbortSignal) =>
    call<BodySizes>(`${bodyApi(id)}/sizes`, signal ? { cache: 'no-cache', signal } : { cache: 'no-cache' }),
  /** Queues resolution `size` of a body; `job_id` null when it is on disk already. */
  generateSize: (id: string, size: string) =>
    call<GenerateStarted>(`${bodyApi(id)}/sizes/${encodeURIComponent(size)}`, { method: 'POST' }),
  /** Deletes an added resolution of a body (never its original). */
  deleteSize: (id: string, size: string) =>
    call<void>(`${bodyApi(id)}/sizes/${encodeURIComponent(size)}`, { method: 'DELETE' }),
  /** Remembers the resolution a body is shown at, in every browser. */
  setDisplayedSize: (id: string, width: number, height: number) =>
    call<void>(`${bodyApi(id)}/displayed-size`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ width, height } satisfies DisplayedSize),
    }),
  jobs: () => call<JobInfo[]>('/api/jobs'),
  cancelJob: (id: string) => call<void>(`/api/jobs/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  /** The drawn systems, most recent first. */
  systems: () => call<SystemSummary[]>('/api/systems'),
  /** Draws a system; in mode `around`, its planet is queued at once (`job_id`). */
  createSystem: (request: SystemRequest, query: SystemQuery = {}) =>
    call<SystemCreated>(query.replace ? '/api/systems?replace=true' : '/api/systems', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(request),
    }),
  deleteSystem: (id: string) => call<void>(`/api/systems/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  /** Names the system itself (the name of its star), keeping its bodies' names; empty brings the designation back. */
  nameSystem: (id: string, name: string) =>
    call<SystemSummary>(`/api/systems/${encodeURIComponent(id)}/name`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name: name.trim() === '' ? null : name.trim() } satisfies SystemName),
    }),
  /** Names one body of a system (`star` too), keeping the other names; empty brings its designation back. */
  nameBody: (id: string, body: string, name: string) =>
    call<SystemSummary>(`/api/systems/${encodeURIComponent(id)}/bodies/${encodeURIComponent(body)}/name`, {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name: name.trim() === '' ? null : name.trim() } satisfies SystemName),
    }),
  /** Pins a system in the main menu, or unpins it; answers its summary. */
  pinSystem: (id: string, pinned: boolean) =>
    call<SystemSummary>(`/api/systems/${encodeURIComponent(id)}/pin`, { method: pinned ? 'PUT' : 'DELETE' }),
  /** Queues a body of a system and its neighbourhood; `job_id` null when they are all generated. */
  generateBody: (id: string, body: string) =>
    call<GenerateStarted>(`/api/systems/${encodeURIComponent(id)}/bodies/${encodeURIComponent(body)}/generate`, {
      method: 'POST',
    }),
  /** The hex map of a body at resolution `size`. */
  hex: (id: string, size: string, request: HexRequest, signal?: AbortSignal) =>
    call<HexMap>(`${bodyApi(id)}/hex?size=${encodeURIComponent(size)}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(request),
      ...(signal ? { signal } : {}),
    }),
};

/** The download of a system's export (`.zip`: seeds, requests, names and PNG images), see `crate::export` on the server. */
export function systemExportUrl(id: string): string {
  return `/api/systems/${encodeURIComponent(id)}/export`;
}

/**
 * A body id as a URL path: a world id, or a moon's `<world>/moons/<n>`
 * (see lib/moons.ts), each segment encoded.
 */
export function bodyPath(id: string): string {
  return id.split('/').map(encodeURIComponent).join('/');
}

/**
 * The id of body `body` of system `system` (docs/system-spec.md), shown as
 * a world is: `systems/<system>/bodies/<body>`, its files under
 * `/systems/…` and its routes under `/api/systems/…`.
 */
export function systemBodyId(system: string, body: string): string {
  return `systems/${system}/bodies/${body}`;
}

/** The system and body of a system body's id (see systemBodyId), or null for a world's. */
export function parseSystemBody(id: string): { system: string; body: string } | null {
  const match = /^systems\/([^/]+)\/bodies\/([^/]+)$/.exec(id);
  return match ? { system: match[1]!, body: match[2]! } : null;
}

/** Where a body's files are served: `/systems/<system>/bodies/<body>` (see systemBodyId). */
export function bodyFiles(id: string): string {
  return `/${bodyPath(id)}`;
}

/** Where a body's routes are: `/api/systems/<system>/bodies/<body>`. */
export function bodyApi(id: string): string {
  return `/api/${bodyPath(id)}`;
}

/**
 * URL of the SVG of a body at resolution `size`. The server draws it when
 * asked and stores nothing: it is not among the body's files.
 */
export function bodySvg(id: string, size: string): string {
  return `${bodyApi(id)}/world.svg?size=${encodeURIComponent(size)}`;
}

/** The name of a resolution, as URLs and `?size=` take it: `2048x1024`. */
export function sizeName(width: number, height: number): string {
  return `${width}x${height}`;
}

/**
 * URL of a file of a generated world at resolution `size` (`WxH`, see
 * sizeName): `/systems/<system>/bodies/<body>/sizes/<size>/<path>`.
 * `revision` (that resolution's modification time, `PresentSize.revision`)
 * makes the URL change when it is regenerated under the same id, so the
 * browser never shows a cached file of the replaced world.
 */
export function worldFile(id: string, size: string, path: string, revision?: number | null): string {
  const url = `${bodyFiles(id)}/sizes/${encodeURIComponent(size)}/${path}`;
  return revision === undefined || revision === null ? url : `${url}?rev=${revision}`;
}

/** The query flag of a peek, see [`peeked`]. */
export const PEEK = 'peek=1';

/**
 * `url` as a peek: a request for a file of a body that is not that body's
 * view. The server records a body as opened (so that it is not evicted
 * after 14 days, docs/analysis/15-storage.md) when its own view loads its
 * files; the textures of other bodies in the sky, the star view's markers
 * and the host planet of a moon carry `peek=1`, which the server does not
 * count. A peek has its own URL, so the browser caches it apart from the
 * body's own load of the same file.
 */
export function peeked(url: string): string {
  return `${url}${url.includes('?') ? '&' : '?'}${PEEK}`;
}

/**
 * URL of the thumbnail of a world (`thumb.png`, 512 pixels wide), which the
 * server makes from `world.png` for worlds generated before thumbnails. With
 * the revision, the browser caches it for good.
 */
export function worldThumbnail(id: string, revision?: number | null): string {
  const url = `${bodyApi(id)}/thumb`;
  return revision === undefined || revision === null ? url : `${url}?rev=${revision}`;
}

const STATUSES: ReadonlySet<string> = new Set(['queued', 'running', 'done', 'failed', 'cancelled']);

/** Whether a job status is final. */
export function isFinished(status: JobStatus): boolean {
  return status.status === 'done' || status.status === 'failed' || status.status === 'cancelled';
}

function isJobStatus(value: unknown): value is JobStatus {
  return (
    typeof value === 'object' &&
    value !== null &&
    STATUSES.has((value as { status?: unknown }).status as string)
  );
}

/**
 * Follows a generation job until it finishes. Calls `onStatus` for every
 * update; resolves with the final status. The returned `cancel` stops listening.
 */
export function followJob(
  jobId: string,
  onStatus: (status: JobStatus) => void,
): { done: Promise<JobStatus>; cancel: () => void } {
  const source = new EventSource(`/api/jobs/${encodeURIComponent(jobId)}/events`);
  const done = new Promise<JobStatus>((resolve) => {
    source.onmessage = (event: MessageEvent<string>) => {
      let parsed: unknown;
      try {
        parsed = JSON.parse(event.data);
      } catch {
        // A malformed event (a proxy's keep-alive, say): wait for the next one.
        return;
      }
      if (!isJobStatus(parsed)) {
        return;
      }
      onStatus(parsed);
      if (isFinished(parsed)) {
        source.close();
        resolve(parsed);
      }
    };
    source.onerror = () => {
      // The server closes the stream after the final status. A stream closed
      // before it means the job is gone: the server restarted, typically
      // because the generation ran out of memory.
      if (source.readyState === EventSource.CLOSED) {
        resolve({
          status: 'failed',
          error:
            'the server stopped during the generation (out of memory?): try a smaller map, or give the server more memory',
        });
      }
    };
  });
  return { done, cancel: () => source.close() };
}
